import warnings
from functools import reduce

from taf.ul.auto_commissioning.utils import remove_nones

from taf.internal.scf.exceptions import ElementNotFound


class ElementFound(Exception):
    pass


class BaseSCFTooDifferentFromDelta(Exception):
    pass


class TAFManagedObjectLocator:

    def __init__(self, taf_int_scf_obj, expect_to_be_present, allow_unexpected, warn_on_unexpected):
        self.mrbts = taf_int_scf_obj.raml.cmData.MRBTS[0]
        self.nrbts = self._get_nrbts_object()
        self.result_filter = InterpreterOfBaseSCFContent(expect_to_be_present, allow_unexpected, warn_on_unexpected)

    def get_correlating_managed_objects(self, pydelta_managed_objects):
        """Does not include None results"""

        return remove_nones([self._locate_and_interpret(mo) for mo in pydelta_managed_objects])

    def locate_and_match_managed_objects(self, pydelta_managed_objects):
        """Find results can be None"""

        return [{"original": self._locate_and_interpret(new_mo), "new": new_mo}
                for new_mo in pydelta_managed_objects]

    def _locate_and_interpret(self, mo):
        taf_mo = self.__locate(mo)
        return self.result_filter.apply_fail_and_warn_on_search_result(taf_mo, mo.dist_name)

    def __locate(self, mo):
        start = self._get_starting_point_for_locators(mo)
        dist_locators = self._load_locators(mo)
        if not dist_locators:
            return start
        try:
            return reduce(lambda obj, locator: getattr(obj, locator), dist_locators, start)
        except ElementNotFound:
            return None

    @staticmethod
    def _load_locators(mo):
        """
        Locators are used upon MRBTS object. They can incorporate NRBTS if such is in distname.
        Managed Objects with NRBTS
        :param distname: example - "TNLSVC-1/TNL-1"
        :return: list of locators
        like:
        ['TNLSVC_1', 'TNL_1']
        """
        if mo.dist_name_without_mr_nr_bts == "":
            return []
        else:
            return mo.dist_name_without_mr_nr_bts.replace("-", "_").split("/")

    def _get_nrbts_object(self):
        try:
            return self.mrbts.NRBTS[0]
        except ElementNotFound:
            return None

    def _get_starting_point_for_locators(self, mo):
        start = self.nrbts if "NRBTS-" in mo.dist_name else self.mrbts
        if start is None:
            raise BaseSCFTooDifferentFromDelta(
                "\n\nYou tried to put delta with NRBTS/(...) or MRBTS/(...) object upon SCF which"
                " has no NRBTS or MRBTS base object.\nIt is not anticipated to have such big difference."
                "\nPlease put any MRBTS or NRBTS object to base SCF first")
        return start

class InterpreterOfBaseSCFContent:

    def __init__(self, expect_to_be_present, allow_unexpected, warn_on_unexpected):
        self.expected = expect_to_be_present
        self.allowed = allow_unexpected
        self.warning = warn_on_unexpected

    def apply_fail_and_warn_on_search_result(self, taf_mo, full_dist_name):
        found = taf_mo
        dist = full_dist_name

        if found and self.expected:
            return found

        elif not found and not self.expected:
            return None

        elif found and not self.expected:
            if not self.allowed:
                raise ElementFound
            else:
                warnings.warn("Element should NOT be found: {}: {}".format(dist, self.warning))
                return found

        elif not found and self.expected:
            if not self.allowed:
                raise ElementNotFound
            else:
                warnings.warn("Element should be found: {}: {}".format(dist, self.warning))
                return None

